lay:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--gap);margin-bottom:12px}.card{border-radius:14px;padding:10px;color:#fff}.c1{background:linear-gradient(135deg,#73d9ef,#5aa8f2)}.c2{background:linear-gradient(135deg,#9cb5ff,#6d90f6)}.c3{background:linear-gradient(135deg,#f5add1,#ea7fbe)}.c4{background:linear-gradient(135deg,#d2bcff,#a88ef0)}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px 8px;text-align:left;border-bottom:1px solid #e2e8f0;color:#334155}th{font-size:12px;text-transform:uppercase;color:#64748b}.pill{font-size:11px;padding:4px 8px;border-radius:999px;background:#eef2ff;color:#4338ca;border:1px solid #c7d2fe}.btn{border:1px solid #c7d2fe;background:#fff;color:#3730a3;border-radius:10px;padding:8px 12px;text-decoration:none;font-size:12px;font-weight:600}.btn-primary{background:linear-gradient(135deg,#6366f1,#4f46e5);color:#fff;border-color:transparent}.modal-backdrop{position:fixed;inset:0;background:rgba(15,23,42,.45);display:none;align-items:center;justify-content:center;z-index:50}.modal-backdrop.show{display:flex}.modal-card{width:min(760px,92vw);background:#fff;border:1px solid #dbe3f1;border-radius:16px;padding:14px;max-height:88vh;overflow:auto}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.form-grid input,.form-grid select,.form-grid textarea{border:1px solid #cbd5e1;border-radius:10px;padding:8px}.span-2{grid-column:span 2}.form-actions{grid-column:span 2;display:flex;justify-content:flex-end;gap:8px}</style></head><body>
