<script>const cModal=document.getElementById('constructionModal');document.getElementById('openConstructionModal').onclick=()=>cModal.classList.add('show');document.getElementById('closeConstructionModal').onclick=()=>cModal.classList.remove('show');document.getElementById('cancelConstructionModal').onclick=()=>cModal.classList.remove('show');cModal.addEventListener('click',e=>{if(e.target===cModal)cModal.classList.remove('show');});</script>
